// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        // Bound _decimals to avoid overflow when computing 10**_decimals
        _decimals = bound(_decimals, 0, 5);
        // Bound v to prevent overflow in v * 10**_decimals
        v = bound(v, 0, 1e18);
        // Assume at least one recipient
        vm.assume(_tos.length > 0);
        // Assume the _tos array does not contain address(0) to avoid trivial revert
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Call transfer and check the return value
        bool result = c.transfer(from, caddress, _tos, v, _decimals);
        assertTrue(result);
    }
}

